import React, { useState } from 'react';
import './App.css';
import UserStoryGenerator from './UserStoryGenerator';
import CodeAnalyzer from './CodeAnalyzer';
import TestCaseGenerator from './TestCaseGenerator';
import FlowWizard from './flows/FlowWizard';

function App() {
  const [activeTab, setActiveTab] = useState('flows');

  return (
    <div className="App">
      <header className="App-header">
        <h1>AI-Powered SDLC Assistant</h1>
        <p className="subtitle">Generate user stories, analyze code, and draft test cases — faster.</p>
        <nav className="tabs" role="tablist" aria-label="Features">
          <button
            className={`tab ${activeTab === 'flows' ? 'active' : ''}`}
            role="tab"
            aria-selected={activeTab === 'flows'}
            onClick={() => setActiveTab('flows')}
          >
            Flows
          </button>
          <button
            className={`tab ${activeTab === 'stories' ? 'active' : ''}`}
            role="tab"
            aria-selected={activeTab === 'stories'}
            onClick={() => setActiveTab('stories')}
          >
            User Stories
          </button>
          <button
            className={`tab ${activeTab === 'analysis' ? 'active' : ''}`}
            role="tab"
            aria-selected={activeTab === 'analysis'}
            onClick={() => setActiveTab('analysis')}
          >
            Code Analysis
          </button>
          <button
            className={`tab ${activeTab === 'tests' ? 'active' : ''}`}
            role="tab"
            aria-selected={activeTab === 'tests'}
            onClick={() => setActiveTab('tests')}
          >
            Test Cases
          </button>
        </nav>
      </header>
      <main>
        {activeTab === 'flows' && <FlowWizard />}
        {activeTab === 'stories' && <UserStoryGenerator />}
        {activeTab === 'analysis' && <CodeAnalyzer />}
        {activeTab === 'tests' && <TestCaseGenerator />}
      </main>
      <footer className="footer">
        <small>Tip: Use short, clear prompts for best results.</small>
      </footer>
    </div>
  );
}

export default App;
